"""PolicyProposal — a candidate defensive action generated by RAG + validated
by deterministic policy rules.

The LLM only ever produces a PolicyProposal JSON. It is NEVER given the
ability to shell out or mutate network state. All actions go through
PolicyValidator → Executor.
"""
from __future__ import annotations

from datetime import datetime, timedelta
from typing import List, Optional, Union

from pydantic import Field, model_validator

from .common import ActionType, DomainModel, PolicyStatus, Severity, _new_id, utcnow


# Parameter schemas per action type — keep them tiny and explicit.
class BlockIpParams(DomainModel):
    ip: str = Field(..., description="Target IP within authorised range.")
    direction: str = Field(default="ingress", pattern="^(ingress|egress|both)$")


class RateLimitParams(DomainModel):
    ip: str
    max_pps: int = Field(..., ge=0, le=1_000_000)
    window_seconds: int = Field(default=60, ge=1, le=3600)


class BlockPortParams(DomainModel):
    port: int = Field(..., ge=0, le=65535)
    protocol: str = Field(default="TCP")


_params_union = Union[BlockIpParams, RateLimitParams, BlockPortParams]


class PolicyProposal(DomainModel):
    """A candidate defensive action."""

    policy_id: str = Field(default_factory=lambda: _new_id("pol"))
    event_id: str  # Must link to a real SecurityEvent

    # Action (whitelisted only)
    action_type: ActionType
    parameters: _params_union

    # Lifecycle
    ttl_seconds: int = Field(default=3600, ge=60, le=86400 * 7)
    risk_level: Severity = Severity.LOW
    evidence_ids: List[str] = Field(default_factory=list)
    rationale: str = Field(..., min_length=1)

    requires_approval: bool = Field(
        default=False,
        description="True for management ports, high-risk assets, or wide CIDRs.",
    )
    status: PolicyStatus = PolicyStatus.DRAFT

    created_at: datetime = Field(default_factory=utcnow)
    expires_at: Optional[datetime] = None

    @model_validator(mode="after")
    def _set_expiry(self) -> "PolicyProposal":
        """Compute expires_at from ttl_seconds if not already set."""
        if self.expires_at is None:
            self.expires_at = self.created_at + timedelta(seconds=self.ttl_seconds)
        return self

    @model_validator(mode="after")
    def _params_match_action(self) -> "PolicyProposal":
        """Ensure the declared parameter shape matches action_type (best-effort)."""
        mapping = {
            ActionType.BLOCK_IP: BlockIpParams,
            ActionType.RATE_LIMIT: RateLimitParams,
            ActionType.BLOCK_PORT: BlockPortParams,
        }
        expected = mapping.get(self.action_type)
        if expected is None:
            return self  # ALERT_ONLY / NO_ACTION can carry any or no params
        if not isinstance(self.parameters, expected):
            raise ValueError(
                f"action_type={self.action_type.value} requires parameters of shape "
                f"{expected.__name__}, got {type(self.parameters).__name__}"
            )
        return self
